using System.Text.Json;
using Autonomous146;
using CoreSim;
using Dynamic160;
using Efficient152;
using LineThrottle156;
using SharedWorldSpeedway;
using ThreeLap158;
using Xunit;
namespace CoreSim.Tests;
[Trait("Shard","core")]
public sealed class DynamicSlipPreview160Tests {
 static RiderSpec Spec=>StandingWorld144.Rider(StartingGate.B);
 static Runtime158 Runtime()=>new(Spec,false,Hierarchical155.Program155.Options());
 [Fact]public void DefaultOffDirectlyDelegatesUnchangedPlanner(){var x=new Controller160(Spec);Assert.NotNull(x.Legacy);Assert.Null(x.Dynamic);Assert.False(new Settings160().Enabled);Assert.Throws<InvalidOperationException>(()=>new Planner160(Spec,false));}
 [Fact]public void EnabledPlannerReusesOriginalRuntimeAndSafety(){var x=new Controller160(Spec,new(Enabled:true,Adaptive:true));Assert.Null(x.Legacy);Assert.IsType<Runtime158>(x.Dynamic!.Runtime);Assert.True(x.Dynamic.Options.Enabled);Assert.Equal(2,x.Dynamic.Options.ObservationDepth);}
 [Fact]public void ProposalOnlyAdaptationDoesNotOfferHistoryTapeSeeding(){Assert.Null(typeof(Planner160).GetMethod("InitializeDiagnosticTape"));Assert.Null(typeof(Planner160).GetMethod("InitializeDiagnosticReview"));}
 [Fact]public void OffControlMatches158BitsWithFullQueue(){var s=Program158.Initial(Spec);s=s with{Input=s.Input with{Time=1,NextReview=1,Omega=10/.33,Steering=.01f,Active=new(.01f,.1f),Rider=s.Input.Rider with{Velocity=new(10,0),Drive=.1f},Pending=new[]{new FreeRacingCommand(.8,1.04,new(-.02f,.2f)),new FreeRacingCommand(.99,1.23,new(.03f,.3f))}}};var original=new Control158(Runtime(),new(10,CourseSeconds:1));var next=new Control160(Runtime(),new(DiagnosticSpeed:10));Assert.Equal(original.Action(s),next.Action(s));Assert.Equal(2,s.Input.Pending.Length);Assert.Equal(1.23,s.Input.Pending[1].ActivationAt);}
 [Fact]public void PhysicalEquilibriumAllowsNonzeroBetaInBend(){var c=new Control160(Runtime(),new(Enabled:true));var straight=c.Equilibrium(12,0);var bend=c.Equilibrium(12,.035);Assert.InRange(Math.Abs(straight.Beta),0,.001);Assert.InRange(straight.Residual,0,.01);Assert.InRange(bend.Beta,.01,.1);Assert.InRange(bend.Residual,0,.01);Assert.InRange(bend.Gas,0,1);}
 [Fact]public void EveryCausalPendingCommandChangesActualPrediction(){var s=Program158.Initial(Spec);s=s with{Input=s.Input with{Time=1,NextReview=1,Omega=10/.33,Active=new(0,.1f),Rider=s.Input.Rider with{Velocity=new(10,0)},Pending=new[]{new FreeRacingCommand(.8,1.04,new(.03f,.2f)),new FreeRacingCommand(.99,1.23,new(-.03f,.3f))}}};var c=new Control160(Runtime(),new(Enabled:true));var a=c.ActivationState(s);Assert.Empty(a.Input.Pending);Assert.Equal(1.23,s.Input.Pending[1].ActivationAt);var changed=s with{Input=s.Input with{Pending=new[]{s.Input.Pending[0],s.Input.Pending[1] with{Action=new(.05f,1)}}}};var p=c.Predict(s,new(0,.1f),.7);var q=c.Predict(changed,new(0,.1f),.7);Assert.NotEqual(p.Points[^1].Rider.Velocity,q.Points[^1].Rider.Velocity);Assert.Equal(2,s.Input.Pending.Length);}
 [Fact]public void ActualMomentProbeStartsAtActualSteering(){var s=Program158.Initial(Spec);s=s with{Input=s.Input with{Time=1,Omega=10/.33,Steering=-.02f,Rider=s.Input.Rider with{Velocity=new(10,0)}}};var c=new Control160(Runtime(),new(Enabled:true));var actual=c.ActualAlpha(s,.4f,.1f);var instantaneous=new Control158(Runtime()).Response(s,.4f,.1f).YawAcceleration;Assert.True(Math.Abs(actual-instantaneous)>1);Assert.Equal(-.02f,s.Input.Steering);}
 [Fact]public void DenseArchivedFailureReproductionIsExact(){var a=Study156.Read<JsonElement>(Program160.Doc+"/forecasts/exact-rest-speed12.json.gz");var b=Study156.Read<JsonElement>(Study156.Root+"/docs/experiments/geometry-speed-audit/forecasts/rest-speed12.json.gz");Assert.Equal(b.GetProperty("End").GetRawText(),a.GetProperty("End").GetRawText());Assert.Equal(b.GetProperty("Points").GetRawText(),a.GetProperty("Points").GetRawText());var aa=a.GetProperty("Actions").EnumerateArray().ToArray();var bb=b.GetProperty("Actions").EnumerateArray().ToArray();Assert.Equal(bb.Length,aa.Length);for(int i=0;i<aa.Length;i++){Assert.Equal(bb[i].GetProperty("State").GetRawText(),aa[i].GetProperty("State").GetRawText());Assert.Equal(bb[i].GetProperty("Action").GetRawText(),aa[i].GetProperty("Action").GetRawText());}}
 [Fact]public void GeneratedProtocolOnlyChangesProposalHooks(){var s=File.ReadAllText(Study156.Root+"/tools/robust-three-lap/Planner158.Generated.cs").Replace("namespace ThreeLap158;","namespace Dynamic160;\nusing ThreeLap158;");foreach(var name in new[]{"Planner","Generator","Settings","Feedback"})s=s.Replace(name+"158",name+"160");s=s.Replace("STUDY158","STUDY160");Assert.Equal(s,File.ReadAllText(Study156.Root+"/tools/dynamic-slip-preview/Planner160.Generated.cs"));}
 [Fact]public void BothIndependentAndSearchStillDetectCorruption(){var s=Program158.Initial(Spec);var rt=Runtime();rt.Begin(0);new Control160(rt,new(Enabled:true)).ActivationState(s);rt.Step(s,new(0,1));rt.CorruptSearchForDiagnostics();using var role=rt.Operation("independent_preflight");Assert.Throws<InvalidOperationException>(()=>rt.Step(s,new(0,1)));}
 [Fact]public void LegacyEndpointInversionMissesInteriorYawResponse(){var a=Study156.Read<JsonElement>(Program160.Doc+"/forecasts/exact-rest-speed12.json.gz").GetProperty("Actions").EnumerateArray().First(q=>Math.Abs(q.GetProperty("State").GetProperty("Input").GetProperty("Time").GetDouble()-7)<1e-8);var state=a.GetProperty("State").Deserialize<State146>(Study156.Json)!;var rt=Runtime();var c=new Control158(rt,new(12,CourseSeconds:1));var future=c.ActivationState(state);var action=a.GetProperty("Action").Deserialize<FreeRacingAction>(Study156.Json);var desired=a.GetProperty("Trace").GetProperty("DesiredAlpha").GetDouble();float max=TwoContactBikeParameters.Default.MaximumSteeringRadians;var left=c.Response(future,-max,action.Drive).YawAcceleration;var right=c.Response(future,max,action.Drive).YawAcceleration;var values=Enumerable.Range(0,141).Select(i=>c.Response(future,-max+2*max*i/140,action.Drive).YawAcceleration).ToArray();Assert.True(desired>left&&desired>right);Assert.True(values.Min()<desired&&values.Max()>desired);Assert.Equal(max,action.SteeringRadians);}
 [Fact]public async Task ParallelBudgetTransactionsPreserveReservations(){var root=Path.GetFullPath(Path.GetTempPath());var directory=Path.Combine(root,"study160-budget-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);try{File.Copy(Program160.Doc+"/budget-plan.json",Path.Combine(directory,"budget-plan.json"));using var a=new Budget160("mock-a","native",true,directory);using var b=new Budget160("mock-b","native",true,directory);Assert.Throws<IOException>(()=>new Budget160("mock-a","native",true,directory));await Task.WhenAll(Task.Run(()=>a.Finish("test")),Task.Run(()=>b.Finish("test")));var rows=Study156.Read<JsonElement>(Path.Combine(directory,"budget-journal.json")).EnumerateArray().ToArray();Assert.Equal(2,rows.Length);Assert.All(rows,r=>Assert.True(r.GetProperty("Complete").GetBoolean()));}finally{Assert.Equal(root.TrimEnd(Path.DirectorySeparatorChar),Path.GetDirectoryName(directory));Directory.Delete(directory,true);}}
 [Fact]public void SaturatedSteeringUsesAdmissibleOneSidedDifference(){float max=TwoContactBikeParameters.Default.MaximumSteeringRadians;foreach(float s in new[]{-max,-max+.001f,0,max-.001f,max}){float probe=Control160.SteeringDifferenceProbe(s);new FreeRacingAction(probe,1).Validate();Assert.NotEqual(probe,s);}Assert.True(Control160.SteeringDifferenceProbe(max)<max);Assert.Throws<ArgumentException>(()=>Control160.SteeringDifferenceProbe(float.NaN));}
 [Fact]public void RecordedDnfProbeExceededSteeringBoundAndRegressionStateNowReturnsValidAction(){var q=Study156.Read<JsonElement>(Program160.Doc+"/certificates/terminal-cause-v5.json.gz").GetProperty("LastProbe");var invalid=q.GetProperty("Action").Deserialize<FreeRacingAction>(Study156.Json);Assert.Throws<ArgumentException>(()=>invalid.Validate());Assert.True(invalid.SteeringRadians>TwoContactBikeParameters.Default.MaximumSteeringRadians);var state=q.GetProperty("Observed").Deserialize<State146>(Study156.Json)!;var c=new Control160(Runtime(),new(Enabled:true,Adaptive:true));c.Action(state).Validate();}
 [Fact]public void NativeSeriesStaysClosedAndHeldFreezeRequiresSuccess(){Assert.Throws<InvalidOperationException>(()=>Gates160.RequireNative(false));Assert.Throws<InvalidOperationException>(()=>Gates160.RequireNative(true));Assert.Throws<InvalidOperationException>(()=>Freeze160.Create());}
 [Fact]public void SixthCertificateConsumesFinalReservation(){var before=File.ReadAllText(Program160.Doc+"/budget-journal.json");Assert.Throws<InvalidOperationException>(()=>new Budget160("must-not-reserve-a-seventh","certificate"));Assert.Equal(before,File.ReadAllText(Program160.Doc+"/budget-journal.json"));}
 [Fact]public void NoInventedSweptIntervalAtTimeZero(){Assert.Null(Native160.MinimumSweep(Array.Empty<double?>()));Assert.Null(Native160.MinimumSweep(new double?[]{.9,null}));Assert.Equal(.6,Native160.MinimumSweep(new double?[]{.8,.6}));}
}
